import * as THREE from 'three';
import { EffectComposer } from 'three/addons/postprocessing/EffectComposer.js';
import { RenderPass } from 'three/addons/postprocessing/RenderPass.js';
import { UnrealBloomPass } from 'three/addons/postprocessing/UnrealBloomPass.js';
import { OutputPass } from 'three/addons/postprocessing/OutputPass.js';
const composer = new EffectComposer(renderer);
composer.setSize(innerWidth, innerHeight);
composer.setPixelRatio(Math.min(devicePixelRatio, 2));
composer.addPass(new RenderPass(scene, camera));
const bloom = new UnrealBloomPass(
new THREE.Vector2(innerWidth, innerHeight),
/* strength */ 0.6,
/* radius */ 0.4,
/* threshold */ 0.85
);
composer.addPass(bloom);
composer.addPass(new OutputPass()); // applies tone mapping + sRGB conversion
renderer.setAnimationLoop(() => {
composer.render(); // not renderer.render
});
window.addEventListener('resize', () => {
composer.setSize(innerWidth, innerHeight);
bloom.setSize(innerWidth, innerHeight);
});
Key points:
composer.render() replaces renderer.render(scene, camera).
RenderPass draws the scene into a render target.
Each subsequent pass reads the previous target and writes a new one.
OutputPass must be last — it applies tone mapping + sRGB. Otherwise colours look wrong.

Approximate ambient occlusion in screen space. Darkens corners.
import { SSAOPass } from 'three/addons/postprocessing/SSAOPass.js';
const ssao = new SSAOPass(scene, camera, innerWidth, innerHeight);
ssao.kernelRadius = 8;
ssao.minDistance = 0.001;
ssao.maxDistance = 0.1;
composer.addPass(ssao);
Expensive. Often the baked AO map (Post 04) is a better answer for static scenes.

Highlight selected objects with an outline.
import { OutlinePass } from 'three/addons/postprocessing/OutlinePass.js';
const outline = new OutlinePass(
new THREE.Vector2(innerWidth, innerHeight), scene, camera
);
outline.edgeStrength = 3.0;
outline.edgeGlow = 0.0;
outline.edgeThickness = 1.0;
outline.visibleEdgeColor.set(0x00ffff);
outline.selectedObjects = [hoveredMesh];
composer.addPass(outline);
Common pattern: raycast on hover → set outline.selectedObjects = [hit.object].

import { BokehPass } from 'three/addons/postprocessing/BokehPass.js';
const dof = new BokehPass(scene, camera, {
focus: 5.0,
aperture: 0.025,
maxblur: 0.01,
width: innerWidth,
height: innerHeight,
});
composer.addPass(dof);
Tweak focus to the distance of your subject; smaller aperture = sharper.

WebGL hardware multisample anti-aliasing (MSAA) is enabled by setting antialias: true on the renderer. MSAA does not work when EffectComposer is used because the render target it allocates by default is single-sample.
Three options:
Pass · Cost · Quality
FXAA (FastApproximateAntiAliasing) · very cheap · OK; blurs everything slightly
SMAA (Subpixel Morphological) · medium · better than FXAA
TAA (Temporal AA) · medium-high; needs jittered camera · best static quality; ghosting on motion
MSAA in composer · high; depends on hardware support · best raw quality
import { ShaderPass } from 'three/addons/postprocessing/ShaderPass.js';
import { FXAAShader } from 'three/addons/shaders/FXAAShader.js';
const fxaa = new ShaderPass(FXAAShader);
fxaa.uniforms.resolution.value.set(1 / innerWidth, 1 / innerHeight);
composer.addPass(fxaa);
For MSAA in a composer, allocate a multisample render target:
const rt = new THREE.WebGLRenderTarget(innerWidth, innerHeight, { samples: 4 });
const composer = new EffectComposer(renderer, rt);
Modern path: use pmndrs/postprocessing library (Chapter 6) — its EffectComposer supports MSAA + multiple effects in one pass.

Built by the pmndrs collective (same as react-three-fiber). Cleaner API, single-pass effect chains (one big shader rather than many small passes — much faster), better-quality effects.
npm install postprocessing
import {
EffectComposer, EffectPass, RenderPass,
BloomEffect, BrightnessContrastEffect, VignetteEffect, SMAAEffect, SMAAPreset
} from 'postprocessing';
const composer = new EffectComposer(renderer);
composer.addPass(new RenderPass(scene, camera));
const effectPass = new EffectPass(
camera,
new SMAAEffect({ preset: SMAAPreset.MEDIUM }),
new BloomEffect({ intensity: 0.7, luminanceThreshold: 0.85 }),
new BrightnessContrastEffect({ contrast: 0.1 }),
new VignetteEffect({ offset: 0.3, darkness: 0.4 })
);
composer.addPass(effectPass);
renderer.setAnimationLoop(() => composer.render());
Effects are composed into one big GPU pass, not chained per-pass — typically 2-4× faster than Three.js's built-in EffectComposer.
R3F has @react-three/postprocessing which wraps the same library declaratively (Post 12).

For a specific "look" (warm filmic, cold thriller, vintage), apply a 3D look-up table (LUT) at the end of the pipeline.
import { LUTPass } from 'three/addons/postprocessing/LUTPass.js';
import { LUTCubeLoader } from 'three/addons/loaders/LUTCubeLoader.js';
const lut = await new LUTCubeLoader().loadAsync('/luts/cinematic.cube');
const lutPass = new LUTPass({ lut: lut.texture3D, intensity: 1.0 });
composer.addPass(lutPass);
Free LUTs: RocketStock 35 free LUTs, IWLTBAP.
pmndrs/postprocessing ships LUT3DEffect with the same idea.
